escenas.animacion:
const acc=A.accent, s=0.92, gY=1090;
A.bg('#0b1a2e','#050b16',true);
const kRapa=A.k('Rapa',1.333), kMoai=A.k('moái',2.333), kCam=A.k('caminaron',2.667), kLug=A.k('lugar.',3.667), kCie=A.k('científicos',4.667), kSer=A.k('serio.',6.0);

// ================= MAPA DE LA ISLA =================
const isl=[[-1,0.3],[-0.6,-0.1],[-0.2,-0.5],[0.1,-0.72],[0.4,-0.4],[0.8,0.1],[1,0.35],[0.6,0.52],[0,0.45],[-0.5,0.56],[-1,0.3]];
const icx=540, icy=1545, isc=250;
const P=(p)=>[icx+p[0]*isc, icy+p[1]*isc];
const ipts=isl.map(P);
const dI=A.p(0.15,1.1,'softInOut'), fI=A.p(1.0,0.5,'softInOut');
if(fI>0){
  ctx.save();ctx.globalAlpha=fI;ctx.beginPath();ipts.forEach((q,i)=>i?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();
  ctx.fillStyle='rgba(30,60,90,0.9)';ctx.fill();ctx.restore();
  A.with(()=>{try{A.lib.hatch(ctx,ipts,{angle:-0.6,spacing:14,width:1.5,color:'rgba(160,200,255,0.25)'});}catch(e){}},{alpha:fI});
}
A.line(ipts,{stroke:'#ffffff',lw:4,progress:dI});
[[-0.85,0.3],[0.1,-0.55],[0.8,0.25]].forEach((v,i)=>{
  const a=A.p(0.9+i*0.15,0.4,'softLand'); if(a<=0)return;
  const q=P(v), h=22;
  A.line([[q[0]-h,q[1]+h*0.5],[q[0],q[1]-h*0.6],[q[0]+h,q[1]+h*0.5]],{stroke:'rgba(255,255,255,0.7)',lw:3,progress:a});
});
if(t>kRapa-0.05) A.label('RAPA NUI',540,1735,{size:46,bg:acc,color:'#0b1a2e',scale:A.pop(kRapa,0.45),alpha:A.p(kRapa,0.3,'softLand')});

// Ruta CANTERA -> AHU
const rA=P([0.55,0.33]), rM=P([0.1,0.05]), rB=P([-0.35,-0.3]);
const w=A.p(kCam,kLug-kCam+0.1,'cruise');
if(t>kMoai-0.05){
  const al=A.p(kMoai,0.35,'softLand');
  A.circle(rA[0],rA[1],12,{fill:acc,alpha:al,glow:14});
  A.text('CANTERA',905,1600,{size:46,color:'#ffffff',weight:'900',align:'center',alpha:al});
  A.line([[rA[0]+14,rA[1]-6],[795,1608]],{stroke:'rgba(255,255,255,0.6)',lw:3,progress:al});
}
if(w>0){
  A.line([rA,rM,rB],{stroke:acc,lw:6,dash:[16,10],progress:w});
  const seg=w<0.5?[rA,rM,w*2]:[rM,rB,(w-0.5)*2];
  const cx=A.lerp(seg[0][0],seg[1][0],seg[2]), cy=A.lerp(seg[0][1],seg[1][1],seg[2]);
  const ddx=seg[1][0]-seg[0][0], ddy=seg[1][1]-seg[0][1], L=Math.hypot(ddx,ddy)||1;
  A.arrow(cx-ddx/L*40,cy-ddy/L*40,cx,cy,{progress:1,color:'#ffffff',lw:6,head:24});
}
if(t>kLug){
  A.rings(rB[0],rB[1],kLug,{count:2,maxR:80,color:acc,lw:4});
  A.circle(rB[0],rB[1],12,{fill:'#ffffff',glow:18});
  A.label('AHU',rB[0]-20,1405,{size:46,bg:acc,color:'#0b1a2e',scale:A.pop(kLug,0.4)});
}

// ================= SUELO =================
A.line([[60,gY],[1020,gY]],{stroke:'rgba(255,255,255,0.8)',lw:4,progress:A.p(0.0,0.6,'softLand')});

// ================= CAMINATA DEL MOÁI =================
const ph2s=kCie+0.5, ph2e=6.45;
const w2=A.clamp((t-ph2s)/(ph2e-ph2s));
const n=3*w+3*w2;
let i=Math.floor(n), u=n-i; if(i>=6){i=5;u=1;}
const eu=0.5-0.5*Math.cos(Math.PI*u);
const mx=400+40*(i+eu);
const side=(i%2===0)?1:-1;
let rot=(n>0&&n<6)?side*0.125*Math.sin(Math.PI*u):0;
if(n===0) rot=Math.sin(t*3)*0.01;
const pivX=mx+side*110*s;
const cr=Math.cos(rot), sr=Math.sin(rot);
const WP=(lx,ly)=>{const x0=mx+lx*s, y0=gY+ly*s, dx=x0-pivX, dy=y0-gY; return [pivX+dx*cr-dy*sr, gY+dx*sr+dy*cr];};

// polvo en el pivote de cada paso
if(n>0&&n<6&&u>0.05){
  A.particles(9,11+i,(q,r)=>{
    const a=r()*Math.PI, d=u*70*r();
    A.circle(pivX+Math.cos(a)*d,gY-Math.sin(a)*d*0.5,3+r()*5,{fill:'#c9b48a',alpha:Math.sin(Math.PI*u)*0.6});
  });
}

const body=[[-110,0],[110,0],[115,-220],[95,-250],[100,-470],[85,-525],[-85,-525],[-100,-470],[-95,-250],[-115,-220]];
const oP=A.p(0.1,1.3,'softInOut'), fillA=A.p(1.2,0.6,'softInOut');
const bump=1+0.07*Math.sin(Math.PI*A.p(kMoai,0.35,'cruise'));
const drawMoai=()=>{
  ctx.save();
  ctx.translate(mx,gY);ctx.scale(bump,bump);ctx.translate(-mx,-gY);
  ctx.translate(pivX,gY);ctx.rotate(rot);ctx.translate(mx-pivX,0);ctx.scale(s,s);
  ctx.globalAlpha=fillA;
  ctx.beginPath();body.forEach((q,k)=>k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();
  const g=ctx.createLinearGradient(-110,0,110,0);g.addColorStop(0,'#5d6474');g.addColorStop(1,'#3a3f4b');
  ctx.fillStyle=g;ctx.fill();
  try{A.lib.hatch(ctx,[[20,0],[110,0],[115,-220],[95,-250],[100,-470],[85,-525],[20,-525]],{angle:0.8,spacing:11,width:2,color:'rgba(0,0,0,0.35)'});}catch(e){}
  ctx.globalAlpha=fillA;
  ctx.lineWidth=5;ctx.strokeStyle='#ffffff';ctx.lineJoin='round';
  ctx.beginPath();body.forEach((q,k)=>k?ctx.lineTo(q[0],q[1]):ctx.moveTo(q[0],q[1]));ctx.closePath();ctx.stroke();
  ctx.fillStyle='#2a2e38';ctx.fillRect(-82,-440,164,22);
  ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-85,-418);ctx.lineTo(85,-418);ctx.stroke();
  ctx.fillStyle='rgba(0,0,0,0.55)';ctx.fillRect(-70,-415,50,22);ctx.fillRect(20,-415,50,22);
  ctx.beginPath();ctx.moveTo(-8,-418);ctx.lineTo(-24,-330);ctx.lineTo(24,-330);ctx.lineTo(8,-418);ctx.stroke();
  ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-40,-295);ctx.quadraticCurveTo(0,-285,40,-295);ctx.stroke();
  ctx.lineWidth=3;ctx.strokeRect(-110,-460,14,170);ctx.strokeRect(96,-460,14,170);
  ctx.lineWidth=4;
  ctx.beginPath();ctx.moveTo(-100,-215);ctx.quadraticCurveTo(-90,-120,-15,-110);ctx.stroke();
  ctx.beginPath();ctx.moveTo(100,-215);ctx.quadraticCurveTo(90,-120,15,-110);ctx.stroke();
  ctx.restore();
};
if(fillA<1){ const op=body.map(q=>WP(q[0],q[1])); op.push(op[0]); A.line(op,{stroke:'#ffffff',lw:5,progress:oP}); }
if(fillA>0) drawMoai();

if(t>kCam && t<kLug+0.6){
  const a=A.p(kCam,0.3,'softLand')*(1-A.p(kLug+0.2,0.4,'softInOut'));
  A.label('¿CAMINARON?',mx,530,{size:58,bg:acc,color:'#0b1a2e',scale:A.pop(kCam,0.45),alpha:a});
}

// ================= CIENTÍFICOS =================
const sci=(x,lean,dir)=>{
  ctx.save();ctx.translate(x,gY);ctx.rotate(lean);
  ctx.strokeStyle='#ffffff';ctx.lineWidth=5;ctx.lineCap='round';ctx.lineJoin='round';
  ctx.beginPath();ctx.moveTo(-8,-55);ctx.lineTo(-18,0);ctx.moveTo(8,-55);ctx.lineTo(18,0);ctx.stroke();
  ctx.beginPath();ctx.moveTo(-22,-122);ctx.lineTo(22,-122);ctx.lineTo(30,-50);ctx.lineTo(-30,-50);ctx.closePath();
  ctx.fillStyle='#e8eef7';ctx.fill();ctx.lineWidth=3;ctx.strokeStyle='#0b1a2e';ctx.stroke();
  ctx.beginPath();ctx.moveTo(0,-122);ctx.lineTo(0,-52);ctx.stroke();
  ctx.strokeStyle='#ffffff';ctx.lineWidth=5;
  ctx.beginPath();ctx.moveTo(dir*10,-112);ctx.lineTo(dir*42,-98);ctx.stroke();
  ctx.beginPath();ctx.arc(0,-144,18,0,Math.PI*2);ctx.fillStyle='#0b1a2e';ctx.fill();ctx.stroke();
  ctx.beginPath();ctx.arc(0,-148,21,Math.PI,0);ctx.closePath();ctx.fillStyle=acc;ctx.fill();
  ctx.fillRect(-27,-150,54,6);
  ctx.restore();
  const hx=dir*42, hy=-98, c=Math.cos(lean), sn=Math.sin(lean);
  return [x+hx*c-hy*sn, gY+hx*sn+hy*c];
};
if(t>kCie-0.15){
  const e1=A.p(kCie-0.15,0.5,'snapSettle'), e2=A.p(kCie+0.05,0.5,'snapSettle');
  const p1x=A.lerp(-100,200,e1), p2x=A.lerp(1180,880,e2);
  const walking2=w2>0&&w2<1;
  const pullL=(walking2&&side<0)?Math.sin(Math.PI*u):0;
  const pullR=(walking2&&side>0)?Math.sin(Math.PI*u):0;
  const hL=sci(p1x,-0.28*pullL,1), hR=sci(p2x,0.28*pullR,-1);
  const rp=A.p(kCie+0.15,0.4,'glide');
  const rope=(h,at,pull)=>{
    const sag=45*(1-pull), pts=[];
    for(let k=0;k<=10;k++){const q=k/10; pts.push([A.lerp(h[0],at[0],q), A.lerp(h[1],at[1],q)+Math.sin(Math.PI*q)*sag]);}
    A.line(pts,{stroke:acc,lw:pull>0.3?7:5,dash:pull>0.3?null:[12,8],progress:rp});
  };
  rope(hL,WP(-80,-400),pullL);
  rope(hR,WP(80,-400),pullR);
  if(pullL>0.15) A.arrow(hL[0]-10,hL[1]-60,hL[0]-10-80*pullL,hL[1]-60,{progress:1,color:'#ffffff',lw:6,head:20});
  if(pullR>0.15) A.arrow(hR[0]+10,hR[1]-60,hR[0]+10+80*pullR,hR[1]-60,{progress:1,color:'#ffffff',lw:6,head:20});
  A.label('CIENTÍFICOS',540,1086,{size:48,bg:acc,color:'#0b1a2e',scale:A.pop(kCie,0.45),alpha:A.p(kCie,0.3,'softLand')});
}

// ================= SELLO =================
if(t>kSer-0.05){
  A.flash(kSer,0.25,0.35);
  A.with(()=>{
    A.label('¡A PRUEBA!',540,505,{size:80,bg:acc,color:'#0b1a2e',scale:A.pop(kSer,0.4)});
  },{x:540,y:505,rot:-0.07,shake:8*(1-A.p(kSer,0.35,'cruise'))});
}

const W=A.W, ac=A.accent||'#FF6B35';
A.bg('#0c1424','#04070d',true);
const tIsla=A.k('isla',0.67), tMil=A.k('mil',2.0), tTall=A.k('tallaron',3.0), tCant=A.k('cantera',4.0), tVol=A.k('volcán',4.67), tRano=A.k('Rano',5.0), tMuch=A.k('muchos',6.0), tPes=A.k('pesan',6.33), tTon=A.k('toneladas',7.0);
const R=A.rand(7);
// ---------- island polygon ----------
const V=[[210,1010],[590,470],[905,930]];
const isl=[];
for(let e=0;e<3;e++){const a=V[e],b=V[(e+1)%3];for(let i=0;i<14;i++){const u=i/14;const n=(R()-0.5)*34;const dx=b[0]-a[0],dy=b[1]-a[1],L=Math.hypot(dx,dy);isl.push([a[0]+dx*u+(-dy/L)*n,a[1]+dy*u+(dx/L)*n]);}}
const islC=isl.concat([isl[0]]);
const cen=[(V[0][0]+V[1][0]+V[2][0])/3,(V[0][1]+V[1][1]+V[2][1])/3];
const RK=[735,890]; // Rano Raraku
const dots=[];const R2=A.rand(21);
for(let i=0;i<110;i++){const j=Math.floor(R2()*isl.length);const p=isl[j],q=isl[(j+1)%isl.length];const u=R2();const x=A.lerp(p[0],q[0],u),y=A.lerp(p[1],q[1],u);const inw=0.05+R2()*0.1;dots.push([A.lerp(x,cen[0],inw),A.lerp(y,cen[1],inw),R2()]);}
// ---------- camera (zoom 1.6x, cantera centrada en 540,800) ----------
const zp=A.p(tCant,1.1,'glide');
const z=A.lerp(1,1.6,zp);
const fx=RK[0], fy=RK[1];
const tx=A.lerp(0,540-RK[0],zp), ty=A.lerp(0,800-RK[1],zp);
const islandAlpha=1-A.p(tMuch-0.15,0.5,'softInOut')*0.85;
const drawP=A.p(0.05,1.6,'softLand');
const rp=A.p(tTall,1.0,'glide');
const kp=A.pop(tTall-0.2,0.5);
const dStart=tIsla+0.5, dEnd=tMil+0.6;
function drawIsland(){
 ctx.save();
 ctx.translate(fx+tx,fy+ty);ctx.scale(z,z);ctx.translate(-fx,-fy);
 ctx.beginPath();islC.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));
 ctx.fillStyle='rgba(255,255,255,'+(0.06*drawP)+')';ctx.fill();
 if(A.lib&&A.lib.hatch&&drawP>0.5){try{A.lib.hatch(ctx,isl,{angle:-0.6,spacing:22,width:1.2,color:'rgba(160,190,230,'+(0.18*drawP)+')'});}catch(e){}}
 A.line(islC,{stroke:'#eaf2ff',lw:4/z*1.4,progress:drawP});
 A.circle(255,975,26,{stroke:'rgba(234,242,255,0.5)',lw:2,alpha:drawP});
 A.circle(590,560,20,{stroke:'rgba(234,242,255,0.4)',lw:2,alpha:drawP});
 if(rp>0){for(let i=0;i<dots.length;i+=9){const d=dots[i];const mx=(RK[0]+d[0])/2+(d[2]-0.5)*80,my=(RK[1]+d[1])/2-30;A.line([[RK[0],RK[1]],[mx,my],[d[0],d[1]]],{stroke:ac,lw:2.2,alpha:0.55,dash:[8,8],progress:A.p(tTall+(i%5)*0.08,0.8,'glide')});}}
 dots.forEach((d)=>{const st=dStart+Math.pow(d[2],0.8)*(dEnd-dStart);const s=A.pop(st,0.4);if(s<=0)return;A.circle(d[0],d[1],5.5*s,{fill:ac,glow:8});});
 if(kp>0){A.with(()=>{ctx.beginPath();ctx.ellipse(RK[0],RK[1],34,24,-0.3,0,Math.PI*2);ctx.fillStyle='#1a2236';ctx.fill();ctx.lineWidth=3;ctx.strokeStyle=ac;ctx.stroke();ctx.beginPath();ctx.ellipse(RK[0],RK[1]+3,20,12,-0.3,0,Math.PI*2);ctx.strokeStyle='rgba(255,255,255,0.6)';ctx.lineWidth=1.5;ctx.stroke();},{x:RK[0],y:RK[1],scale:kp});}
 if(t>tVol)A.rings(RK[0],RK[1],tVol,{count:3,speed:60,gap:0.35,maxR:90,color:ac,lw:2,alpha:0.8*(1-A.p(tMuch,0.4))});
 ctx.restore();
}
// isla enmascarada entre y 400 y 1130, con desvanecido suave en el borde superior
const bands=[[400,425,0.25],[425,450,0.5],[450,475,0.8],[475,1130,1]];
bands.forEach(b=>{ctx.save();ctx.beginPath();ctx.rect(0,b[0],W,b[1]-b[0]);ctx.clip();ctx.globalAlpha=islandAlpha*b[2];drawIsland();ctx.restore();});
// etiqueta RAPA NUI bajo el contorno
const rnIn=A.p(tIsla,0.5,'softLand'), rnOut=A.p(tCant-0.3,0.4,'accelExit');
if(rnIn>0&&rnOut<1){A.text('RAPA NUI',560,1068+(1-rnIn)*20,{size:46,color:'#eaf2ff',weight:800,align:'center',alpha:rnIn*(1-rnOut)*0.9});}
// ---------- secondary zone texts ----------
const cIn=A.p(tMil-0.1,0.5,'softLand'), cOut=A.p(tCant-0.2,0.4,'accelExit');
if(cIn>0&&cOut<1){const v=A.counter(0,1000,A.p(tMil-0.1,1.1,'expo.out'),0);const vs=Number(v.replace(/[^0-9]/g,''));const txt=vs>=1000?'1.000':String(vs);
A.text('~'+txt,540,1520+(1-cIn)*40-cOut*40,{size:170,color:ac,weight:900,align:'center',alpha:cIn*(1-cOut)});
A.text('MOÁI',540,1640-cOut*40,{size:62,color:'#fff',weight:800,align:'center',alpha:cIn*(1-cOut)});}
const l1=A.p(tCant,0.4,'softLand'), l1o=A.p(tMuch-0.2,0.35,'accelExit');
if(l1>0&&l1o<1){A.label('CANTERA',540,1430,{size:58,bg:ac,color:'#0c1424',scale:A.pop(tCant,0.4),alpha:1-l1o});}
const l2=A.p(tRano,0.45,'softLand');
if(l2>0&&l1o<1){A.text('VOLCÁN',540,1560,{size:48,color:'#cfd9ea',weight:700,align:'center',alpha:A.p(tVol,0.4)*(1-l1o)});A.text('RANO RARAKU',540,1650+(1-l2)*30,{size:84,color:'#fff',weight:900,align:'center',alpha:l2*(1-l1o)});}
// ---------- big moai ----------
const mp=A.p(tMuch-0.05,0.45,'crashIn');
if(mp>0){
 const land=tMuch+0.4;
 const shake=t>land&&t<land+0.35?14*(1-(t-land)/0.35):(t>tTon&&t<tTon+0.4?18*(1-(t-tTon)/0.4):0);
 const base=1110, h=600, cx=470;
 const yOff=A.lerp(-1300,0,mp);
 A.with(()=>{
  A.line([[120,base],[960,base]],{stroke:'#eaf2ff',lw:4,progress:A.p(tMuch,0.4,'softLand')});
  const cr=A.p(tTon,0.35,'crashIn');
  if(cr>0){[[-1,0.2],[1,0.5],[-1,0.8],[1,0.1]].forEach((c,i)=>{A.line([[cx+c[0]*60,base],[cx+c[0]*(110+i*20),base+18],[cx+c[0]*(150+i*30),base+8+i*6]],{stroke:ac,lw:3,progress:cr});});}
  ctx.save();ctx.translate(0,yOff);
  const P=[[-0.21,0],[-0.22,-0.5],[-0.16,-0.56],[-0.15,-0.6],[-0.19,-0.9],[-0.17,-1],[0.17,-1],[0.19,-0.9],[0.15,-0.6],[0.16,-0.56],[0.22,-0.5],[0.21,0]].map(p=>[cx+p[0]*h,base+p[1]*h]);
  ctx.beginPath();P.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.closePath();
  const g=ctx.createLinearGradient(cx-0.22*h,0,cx+0.22*h,0);g.addColorStop(0,'#3a4152');g.addColorStop(1,'#1c212c');ctx.fillStyle=g;ctx.fill();
  if(A.lib&&A.lib.hatch){try{A.lib.hatch(ctx,[[cx+0.02*h,base],[cx+0.02*h,base-h],[cx+0.19*h,base-h],[cx+0.22*h,base-0.5*h],[cx+0.21*h,base]],{angle:0.8,spacing:12,width:1.5,color:'rgba(0,0,0,0.45)'});}catch(e){}}
  ctx.lineWidth=5;ctx.strokeStyle='#eaf2ff';ctx.lineJoin='round';ctx.stroke();
  const X=(u)=>cx+u*h, Y=(v)=>base-v*h;
  const sh=ctx.createLinearGradient(0,Y(0.86),0,Y(0.76));sh.addColorStop(0,'rgba(0,0,0,0.45)');sh.addColorStop(1,'rgba(0,0,0,0)');
  ctx.fillStyle=sh;ctx.fillRect(X(-0.17),Y(0.86),0.34*h,0.1*h);
  [-1,1].forEach(sd=>{const ex=X(sd*0.09),ey=Y(0.805);
   const rg=ctx.createRadialGradient(ex,ey-2,1,ex,ey,26);rg.addColorStop(0,'rgba(0,0,0,0.85)');rg.addColorStop(0.6,'rgba(0,0,0,0.4)');rg.addColorStop(1,'rgba(0,0,0,0)');
   ctx.fillStyle=rg;ctx.beginPath();ctx.ellipse(ex,ey,26,13,0,0,Math.PI*2);ctx.fill();
   ctx.beginPath();ctx.ellipse(ex,ey-1,16,6,0,0,Math.PI*2);ctx.fillStyle='rgba(0,0,0,0.6)';ctx.fill();
  });
  ctx.lineCap='round';ctx.strokeStyle='#eaf2ff';ctx.lineWidth=9;
  ctx.beginPath();ctx.moveTo(X(-0.175),Y(0.83));ctx.quadraticCurveTo(X(-0.1),Y(0.875),X(-0.02),Y(0.845));ctx.stroke();
  ctx.beginPath();ctx.moveTo(X(0.175),Y(0.83));ctx.quadraticCurveTo(X(0.1),Y(0.875),X(0.02),Y(0.845));ctx.stroke();
  ctx.fillStyle='rgba(0,0,0,0.25)';
  ctx.beginPath();ctx.moveTo(X(0.015),Y(0.84));ctx.lineTo(X(0.055),Y(0.72));ctx.quadraticCurveTo(X(0.07),Y(0.69),X(0.04),Y(0.685));ctx.lineTo(X(0.0),Y(0.69));ctx.closePath();ctx.fill();
  ctx.lineWidth=4;
