      A.circle(x+vx*d, g+vy*d+120*d*d, 5+r()*9,{fill:'#b8c8d0',alpha:0.6*Math.max(0,1-d/1.3)});});
  }
  A.flash(imp,0.18,0.25);
},{shake});

// TIRADO label
if(t>imp){const a=1-A.p(tTi,0.35,'accelExit'); if(a>0) A.label('TIRADO',640,690,{size:52,bg:acc,color:'#06101c',scale:A.pop(imp),alpha:a});}

// base label + width dimension
if(t>tB){const a=1-A.p(tAv,0.3,'accelExit');
  if(a>0){const bx0=mx0, bx1=mx0+PV*2, yy=g+50;
    A.arrow((bx0+bx1)/2,yy,bx0,yy,{progress:A.p(tB,0.4),color:acc,lw:4,alpha:a});
    A.arrow((bx0+bx1)/2,yy,bx1,yy,{progress:A.p(tB,0.4),color:acc,lw:4,alpha:a});
    A.label('BASE ANCHA',(bx0+bx1)/2+40,g+110,{size:44,bg:acc,color:'#06101c',scale:A.pop(tB+0.15),alpha:a});}
}

// inclination indicator
if(leanP>0){const P=[mx+PV,g], L=440, a=A.clamp(leanP*2);
  A.line([P,[P[0],P[1]-L]],{stroke:'#ffffff',lw:3,dash:[12,12],alpha:0.7*a});
  A.line([P,[P[0]+L*Math.sin(rot),P[1]-L*Math.cos(rot)]],{stroke:warm,lw:5,alpha:a});
  ctx.save(); ctx.strokeStyle=warm; ctx.lineWidth=6; ctx.globalAlpha=a;
  ctx.beginPath(); ctx.arc(P[0],P[1],330,-Math.PI/2,-Math.PI/2+rot,rot<0); ctx.stroke(); ctx.restore();
  A.label('INCLINADO',P[0]+300,560,{size:46,bg:warm,color:'#06101c',scale:A.pop(tI+0.2),alpha:a});
}

// walk arrow
if(t>tAv){
  A.arrow(mx0+260,1080,mx0+640,1080,{progress:A.p(tAv,0.5,'whip'),color:acc,lw:8,head:26});
  A.text('AVANZA',mx0+450,1060,{size:44,color:acc,weight:'900',align:'center',alpha:A.p(tAv+0.2,0.3)});
  A.rings(mx+PV,g,tAv+0.25,{count:3,speed:260,gap:0.22,maxR:120,color:acc,lw:3,alpha:0.5});
}

// secondary: map of ancient roads
const mA=A.p(tAnt-0.3,0.4,'softInOut')*(1-0.6*A.p(tTi,0.5,'softInOut'));
if(mA>0){
  ctx.save(); ctx.globalAlpha=mA;
  A.lib.inkPath(ctx,[[90,1640],[170,1530],[200,1555],[250,1640]],{width:4,color:ink,closed:true,fill:'#1d3242'});
  A.text('RANO RARAKU',170,1690,{size:28,color:'#9fb6c4',weight:'700',align:'center'});
  const path=[]; for(let i=0;i<=40;i++){const x=240+i*18.5; path.push([x,1600-i*3+38*Math.sin(i*0.33)]);}
  A.line(path,{stroke:acc,lw:5,dash:[14,10],progress:A.p(tAnt-0.3,0.9,'glide')});
  [10,18,26,34].forEach((idx,j)=>{const s=A.pop(tAnt+0.1+j*0.15); if(s>0){const [px,py]=path[idx];
    A.with(()=>{A.rect(px-22,py-30,44,16,{r:6,fill:'#2f4556',stroke:ink,lw:2});},{x:px,y:py-22,scale:s});}});
  A.text('CAMINOS ANTIGUOS',640,1410,{size:38,color:acc,weight:'900',align:'center',alpha:A.p(tAnt,0.4)});
  ctx.restore();
}

const W=A.W, acc=A.accent, D=Math.PI/180;
A.bg('#0b1630','#050a18',true);
const tSig=A.k('Síguenos',0), tChile=A.k('Chile',1.667), tMundo=A.k('mundo.',2.667), tSab=A.k('¿Sabías',3.0), tMoai=A.k('moái',4.0), tCam=A.k('caminaban?',4.333);
const G=1090;
// suelo
A.line([[60,G],[1020,G]],{stroke:'#8fb3ff',lw:4,alpha:0.6});
A.particles(14,7,(i,r)=>{const x=80+i*68+r()*20; A.line([[x,G+12],[x+30,G+12]],{stroke:'#8fb3ff',lw:2,alpha:0.22});});

// ---- movimiento del moái ----
const sd=0.45, x0=300, stepPx=50;
let rot, bx, landShake=0;
if(t<tSab){ rot=4*D*Math.sin(t*2*Math.PI/1.0); bx=x0; }
else{
  const u=(t-tSab)/sd;
  if(u>=4){ rot=0; bx=x0+stepPx*4; }
  else{
    const k=Math.floor(u), p=u-k, side=(k%2)?-1:1;
    rot=side*8*D*Math.sin(Math.PI*p);
    const e=p<0.5?2*p*p:1-Math.pow(-2*p+2,2)/2;
    bx=x0+stepPx*(k+e);
  }
  for(let k=0;k<4;k++){const tl=tSab+(k+1)*sd; const a=t-tl; if(a>0&&a<0.2) landShake=Math.max(landShake,(1-a/0.2)*5);}
}
const sc=A.lerp(0.9,1.0,A.p(tSab,0.5,'glide'));
const off=rot>=0?110:-110;
function toW(lx,ly){const rx=(lx-off)*sc, ry=ly*sc, c=Math.cos(rot), s=Math.sin(rot); return [bx+off*sc+rx*c-ry*s, G+rx*s+ry*c];}

// ---- pisadas y polvo ----
for(let k=0;k<4;k++){
  const tl=tSab+(k+1)*sd; if(t<tl) continue;
  const side=(k%2)?-1:1, bk=x0+stepPx*(k+1);
  const cxL=bk+(side===1?-110:110);
  const fa=A.p(tl,0.25,'softLand');
  A.rect(cxL-22,G+8,44,8,{r:4,fill:acc,alpha:0.55*fa});
  A.rings(cxL,G,tl,{count:1,speed:240,maxR:90,color:acc,lw:3,alpha:0.5});
  A.particles(9,30+k,(i,r)=>{const age=t-tl; if(age>0.7) return; const ang=-Math.PI*(0.08+r()*0.84); const dist=age*(90+r()*120); const life=1-age/0.7;
    A.circle(cxL+Math.cos(ang)*dist, G+Math.sin(ang)*dist*0.55, (4+r()*6)*life,{fill:'#d8c49a',alpha:0.7*life});});
}

// ---- cuerdas ----
const rp=A.p(tSab+0.15,0.4,'glide');
if(rp>0){
  const hl=toW(-104,-470), hr=toW(104,-470);
  const ends=[[-30,700],[W+30,700]];
  [[hl,ends[0],rot<0],[hr,ends[1],rot>0]].forEach(([a,b,taut])=>{
    const tension=taut?Math.min(1,Math.abs(rot)/(5*D)):0;
    const sag=A.lerp(60,0,tension);
    const pts=[]; for(let i=0;i<=16;i++){const f=i/16; pts.push([A.lerp(a[0],b[0],f), A.lerp(a[1],b[1],f)+Math.sin(Math.PI*f)*sag]);}
    A.line(pts,{stroke:taut&&tension>0.3?acc:'#eaf2ff',lw:taut?5:3,alpha:taut?0.95:0.6,progress:rp});
  });
}

// ---- moái ----
function moai(){
  const pts=[[-110,0],[110,0],[118,-230],[100,-290],[92,-320],[104,-470],[84,-525],[-84,-525],[-104,-470],[-92,-320],[-100,-290],[-118,-230]];
  A.lib.inkPath(ctx,pts,{width:5,color:'#eaf2ff',closed:true,fill:'#2a2f3d'});
  A.lib.hatch(ctx,[[20,0],[110,0],[118,-230],[100,-290],[92,-320],[104,-470],[84,-525],[20,-525]],{angle:0.8,spacing:13,width:2,color:'rgba(140,170,230,0.45)'});
  const lw='#eaf2ff';
  A.line([[-92,-440],[92,-440]],{stroke:lw,lw:6});
  A.rect(-78,-438,58,30,{r:6,fill:'#10131c'}); A.rect(20,-438,58,30,{r:6,fill:'#10131c'});
  A.line([[0,-440],[-16,-350],[16,-350],[0,-440]],{stroke:lw,lw:4});
  A.line([[-40,-330],[40,-330]],{stroke:lw,lw:5});
  A.line([[-95,-200],[-60,-90],[10,-70]],{stroke:lw,lw:4,alpha:0.8});
  A.line([[95,-200],[60,-90],[-10,-70]],{stroke:lw,lw:4,alpha:0.8});
}
A.with(()=>{
  ctx.save(); ctx.translate(bx+off*sc,G); ctx.rotate(rot); ctx.translate(-off*sc,0); ctx.scale(sc,sc);
  moai(); ctx.restore();
},{shake:landShake});

// ---- Chile + mundo (derecha), sale antes de que el moái camine ----
const ex=A.p(tSab,0.45,'accelExit');
if(t>tChile-0.05 && ex<1){
  const cx=800, cy=820, R=190;
  ctx.save(); ctx.globalAlpha=1-ex; ctx.translate(700*ex,0);
  const gl=A.p(tMundo,0.6,'snapSettle');
  if(gl>0){
    A.circle(cx,cy,R*gl,{fill:'#0e2148',stroke:'#eaf2ff',lw:5});
    ctx.save(); ctx.strokeStyle='rgba(234,242,255,0.45)'; ctx.lineWidth=3;
    for(let m=0;m<3;m++){ctx.beginPath(); ctx.ellipse(cx,cy,Math.max(1,R*gl*(0.3+m*0.33)*Math.abs(Math.cos(t*1.5+m))),R*gl,0,0,Math.PI*2); ctx.stroke();}
    ctx.beginPath(); ctx.ellipse(cx,cy,R*gl,60*gl,0,0,Math.PI*2); ctx.stroke(); ctx.restore();
    A.rings(cx,cy,tMundo,{count:2,speed:320,maxR:260,color:acc,lw:3,alpha:0.45});
    const em=A.pop(tMundo+0.1,0.45);
    A.with(()=>{A.text('EL MUNDO',0,0,{size:50,color:'#ffffff',weight:900,align:'center',stroke:'#050a18',strokeWidth:8});},{x:cx,y:1050,scale:em});
  }
  const chile=[]; for(let i=0;i<=20;i++){chile.push([cx-10-i*1.0+Math.sin(i*1.3)*5, 680+i*14]);}
  A.line(chile,{stroke:acc,lw:12,progress:A.p(tChile,0.6,'glide')});
  const cp=A.pop(tChile+0.1,0.45);
  A.with(()=>{A.text('CHILE',0,0,{size:62,color:acc,weight:900,align:'center',stroke:'#050a18',strokeWidth:9});},{x:cx,y:585,scale:cp});
  ctx.restore();
}

// ---- "?" junto a la cabeza -> ¡CAMINABAN! ----
if(t>tSab && t<tMoai+0.25){
  const pq=A.pop(tSab+0.1,0.45)*(1-A.p(tMoai,0.25,'accelExit'));
  const hx=toW(104,-470);
  A.with(()=>{A.text('?',0,0,{size:150,color:acc,weight:900,align:'center',stroke:'#050a18',strokeWidth:8});},{x:Math.min(hx[0]+90,980),y:600+Math.sin(t*5)*8,scale:pq,rot:0.12});
}
if(t>tMoai){
  const pc=A.pop(tMoai,0.45);
  A.with(()=>{A.label('¡CAMINABAN!',0,0,{size:76,bg:acc,color:'#0b1630'});},{x:540,y:480,scale:pc,rot:Math.sin(t*6)*0.02});
  A.flash(tCam,0.2,0.25);
}

// ---- botón seguir (zona secundaria) ----
const fb=A.p(tSig+0.1,0.5,'softLand');
A.with(()=>{A.follow(540,1520,0.2,1.3);},{alpha:fb,y:(1-fb)*80});
